"use strict";

angular
	.module("irtech.netcity.em.statforms")
	.controller("StatFormsCtrl", ($scope, $appLoader, $location, $alerts, $q, $http, statFormsRepository) => {

		$scope.$parent.page = {
			title: language.Generic.EMReportNames.kStatisticWatchingForm
		};

		$.extend($scope, {
			language: language,
			state: {
				dataReady: false,
				emptyData: false
			},
			data: {
				years: [],
				year: null,
				forms : []
			}
		});

		//переход в экран экспорта
		$scope.goExportStatForms = () => {
			$location.path("/export/");
		}

		//переход в экран экспорта
		$scope.goFillingControl = () => {
			$location.path("/fillingcontrol/");
		}

		$scope.goToLink = (link) => {
			if (link == '') {
				alert(language.Generic.ReportNames.kReportUnavailable);
				return;
			}
			postTo(link);
		};

		const loadForms = () => {
			let globalYearId = appContext.globalYearId;

			return statFormsRepository.getFormList(globalYearId)
				.then((forms) => {
					$scope.data.forms = forms;
				});
		};

		const formListReady = loadForms();

		const yearsReady = statFormsRepository.getYears()
			.then((years) => {
				$scope.data.years = years;
			});

		const collectionsReady = $q.all([yearsReady, formListReady]);

		const contextYearChange = (setYearId) => {
			return $http.post("/webapi/context/year", setYearId)
				.then(() => {
					return $q.resolve(setYearId);
				});
		};

		const loadContextYear = () => {
			const setYearId = $scope.data.year.id;

			return contextYearChange(setYearId)
				.then((year) => {
					appContext.globalYearId = year;
				});
		};

		// обрабатывает изменения фильтра Учебный год
		$scope.onYearChange = () => {
			$q.when(loadContextYear()).then(() => loadForms());
		}

		//загрузка данных
		$scope.load = () => {
			//todo. загрузка списка уч. годов
			//todo. загрузка списка форм

			collectionsReady.then(() => {
				$scope.data.year = _.findWhere($scope.data.years, { id: appContext.globalYearId });

				$scope.state.dataReady = false;
				$appLoader.hide();
			});
		}

		$scope.load();
	});



