"use strict";

import { BaseRepository } from "approot/global/repository.js";

class StatFormsRepository extends BaseRepository {
	getFormList(globalYearId) {
		return this.$http.get("/webapi/em/statforms/list", globalYearId)
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	// возвращает коллекцию годов
	getYears() {
		return this.$http.get("/webapi/em/years")
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	exportForm(yearId, formId) {
		let emId = appContext.emId;
		let isMns = false;

		postTo({
			path: "/webapi/em/statforms/export",
			formParams: {
				method: "GET",
				target: "_blank"
			},
			params: { emId: emId, globalYearId: yearId, form: formId, isMns: isMns }
		});
	}

	exportAggregateForm(yearId, formId) {
		let emId = appContext.emId;
		let formSpec = 0;

		postTo({
			path: "/webapi/em/statforms/aggregate",
			formParams: {
				method: "GET",
				target: "_blank"
			},
			params: { emId: emId, globalYearId: yearId, form: formId, formSpec: formSpec }
		});
	}

	getFillingInfo(yearId, formId) {
		//todo. реализовать загрузку
	}
}


angular
		.module("irtech.netcity.em.statforms")
		.factory("statFormsRepository", ($http, $dialogs, $alerts) => new StatFormsRepository($http, $dialogs, $alerts))
	;


