"use strict";

import { filterPanel } from "webroot/vendor/pages/js/filters.coffee";
import FillingStatFormInfoCtrl from "webroot/vendor/pages/js/fillingStatFormInfo.js";

angular
	.module("irtech.netcity.em.statforms")
	.controller("FillingControlStatFormsCtrl", ($scope, $appLoader, $http, $alerts, statFormsRepository) => {

		//todo. заменить на языковые константы
		$scope.$parent.page = {
			parent: {
				title: language.Generic.EMReportNames.kStatisticWatchingForm,
				href: "/"
			},
			title: language.Generic.EMReportNames.kFillingControl
		};

		$.extend($scope, {
			language: language,
			state: {
				dataReady: false,
				emptyData: false
			},
			data: {
				yearId: null,
				formId: null
			},
			filterInfo: {
				filterPanel: null
			},
			fillingStatFormInfoCtrl: null
		});

		//todo. реализация фильтр-панели
		const fpUrl = "/webapi/em/schools/statforms/filterpanels/fillingInfo";
		const fpInitUrl = "/webapi/em/schools/statforms/fillingInfo/initfilters";

		// инициализация контроллера для вывода информации по заполняемости форм
		const initFillingStatFormInfoCtrl = () => {
			if ($scope.fillingStatFormInfoCtrl) {
				return $scope.fillingStatFormInfoCtrl;
			}

			let sfp = $('#statFormInfoPanel');
			let fp = $scope.filterInfo.filterPanel;

			$scope.fillingStatFormInfoCtrl = new FillingStatFormInfoCtrl(sfp, fp);
		}

		$http.get(fpUrl)
			.then((response) => {
				const fpInfo = response.data.filterPanel;
				const fpSources = response.data.filterSources;
				const fltPanel = $(".filters-panel");

				$scope.filterInfo.filterPanel = new filterPanel(fltPanel, fpInfo, fpSources, fpInitUrl);
				$appLoader.hide();

				initFillingStatFormInfoCtrl();
			});

		$scope.browseStatFormInfo = () => {
			$scope.fillingStatFormInfoCtrl.browseStatFormInfo();
		};

		$scope.openToEdit = () => {
			$scope.fillingStatFormInfoCtrl.openToEdit();
		};

		$scope.print = () => {
			$scope.fillingStatFormInfoCtrl.print();
		};

		$scope.export = () => {
			$scope.fillingStatFormInfoCtrl.export();
		};

		$scope.reopenForms = () => {
			$scope.fillingStatFormInfoCtrl.reopenForms();
		};

		$scope.cancel = () => {
			$scope.fillingStatFormInfoCtrl.cancel();
		};

		$scope.getForEditing = () => {
			if (!$scope.fillingStatFormInfoCtrl) {
				return false;
			}
			return $scope.fillingStatFormInfoCtrl.getForEditing();
		};
	});



