"use strict";

import { filterPanel } from "webroot/vendor/pages/js/filters.coffee";

angular
	.module("irtech.netcity.em.statforms")
	.controller("ExportStatFormsCtrl", ($scope, $appLoader, $http, $alerts, statFormsRepository, downloadService) => {

		$scope.$parent.page = {
			parent: {
				title: language.Generic.EMReportNames.kStatisticWatchingForm,
				href: "/"
			},
			title: language.Generic.EMReportNames.kReportExportStatForms
		};

		$.extend($scope, {
			state: {
				filterChanged: false,
				dataReady: false,
				emptyData: false
			},
			data: {
				yearId: null,
				formId: null
			},
			filterInfo: {
				filterPanel: null
			}
		});

		// todo. реализация фильтр-панели
		const fpUrl = "/webapi/em/statforms/export/filter";
		const fpInitUrl = "/webapi/em/statforms/export/initfilters";

		$http.get(fpUrl)
			.then((response) => {
				const fpInfo = response.data.filterPanel;
				const fpSources = response.data.filterSources;
				const fltPanel = $(".filters-panel");

				$scope.filterInfo.filterPanel = new filterPanel(fltPanel, fpInfo, fpSources, fpInitUrl);
				$appLoader.hide();
			});

		const getExportParams = () => {
			let fp = $scope.filterInfo.filterPanel;

			let yearId = fp.getValues().YEAR;
			let formId = fp.getValues().STATFORMID;

			let emId = appContext.emId;

			let params = {
				emId: emId,
				globalYearId: yearId,
				form: formId
			};

			return params;
		}

		const download = (url, params) => {
			var processing = $.show.processing();
			downloadService.downloadFile(`${url}?${$.param(params)}`)
				.then(() => {
					processing.close();
				})
				.catch(() => processing.close());
		}

		$scope.exportAggregateForm = () => {
			let params = getExportParams();
			params.formSpec = 0;

			download("/webapi/em/statforms/aggregate", params);
		};

		$scope.exportForm = () => {
			let params = getExportParams();
			params.isMns = false;

			download("/webapi/em/statforms/export", params);
		};
	});



