const module = angular.module("irtech.netcity.em.statforms",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./repository.js");
require("./list/statFormsCtrl.js");
require("./export/exportStatFormsCtrl.js");
require("./fillingcontrol/fillingControlCtrl.js");
 
module.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/list/", {
			templateUrl: "/static/dist/app/em/statForms/list/template.html",
			controller: "StatFormsCtrl"
		})
		.when("/export/", {
			templateUrl: "/static/dist/app/em/statForms/export/template.html",
			controller: "ExportStatFormsCtrl"
		})
		.when("/fillingcontrol/", {
			templateUrl: "/static/dist/app/em/statForms/fillingcontrol/template.html",
			controller: "FillingControlStatFormsCtrl"
		})
		.otherwise({
			templateUrl: "/static/dist/app/em/statForms/list/template.html",
			controller: "StatFormsCtrl"
		});
	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});


